import csv
from collections import defaultdict

targets = {
    'AHU03': 'f0a0044c-9c90-58fc-b425-307d0c874a2a',       # SupplyFan_AHU03_Electric_Power_Sensor
    'SupplyFan_AHU01': '47f1370e-62d8-56c6-8ae6-d34fa69cf177',
    'SupplyFan_AHU02': '03f8d175-8f4f-5a5c-8017-4cac0978dde8',
}

day = '2018-01-17'
energy = defaultdict(float)
counts = defaultdict(int)

with open(VALUES_CSV) as f:
    r = csv.DictReader(f)
    for row in r:
        tsid = row['timeseries_id']
        if tsid in targets.values():
            ts = row['timestamp']
            if ts.startswith(day):
                try:
                    v = float(row['value'])
                except ValueError:
                    continue
                # sample assumed constant for 1 hour
                for name, tid in targets.items():
                    if tid == tsid:
                        energy[name] += v * 3600.0   # Wh
                        counts[name] += 1
                        break

for name in targets:
    print(name, 'samples=', counts[name], 'Wh=', energy[name], 'kWh=', energy[name]/1000)

best = max(energy, key=energy.get)
print('BEST:', best)
